test_setup_files.behavior_test.js:
const assert = require('assert');
const { buildConfig } = require('./build/config.js');
assert.deepStrictEqual(buildConfig('http://a', {}),
  { url: 'http://a', retries: 3, backoffMs: 100 }, 'defaults must apply');
assert.deepStrictEqual(buildConfig('http://a', { retries: 7 }),
  { url: 'http://a', retries: 7, backoffMs: 100 });
assert.deepStrictEqual(buildConfig('http://a', { retries: 0, backoffMs: 0 }),
  { url: 'http://a', retries: 0, backoffMs: 0 }, 'explicit 0 overrides must win over defaults');
console.log('PASS');

